Here's an example code snippet that demonstrates this:

```html
<input type="text" id="input-field" placeholder="Enter something...">
<span class="icon-container">
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="icon">
    <path d="M22 12h-4l-4 4h-4v4h-2v-4l-4-4H6l8-8z"></path>
  </svg>
</span>

<script>
  const inputField = document.getElementById('input-field');
  const icon = document.querySelector('.icon');

  icon.addEventListener('click', () => {
    // Call the onClick function here
    onClick();
  });

  // You can also add a click event listener to the input field to call the onClick function when the input field loses focus
  inputField.addEventListener('blur', () => {
    onClick();
  });
</script>

